<script setup>
import { computed,ref,nextTick,watch } from 'vue';
import { useRoute } from 'vue-router';
import { NButton,NCheckbox,NSelect,NModal } from 'naive-ui';
import { store,bootstrap } from '../lib/store';
import { fail,toast } from '../lib/ui';
import { countdown,deadlineLocal,conferenceState,conferenceSummary,sortConferences } from '../lib/deadlines';
import { updateConference,useDeadlineClock } from '../lib/conferences';
const route=useRoute(),now=useDeadlineClock(),busy=ref({}),expanded=ref({}),area=ref('all'),onlyPlanned=ref(false),targetKey=ref(null),targetProject=ref(null);
const options=computed(()=>[{label:'全部方向',value:'all'},...[...new Set(store.conferences.map(c=>c.area))].map(value=>({label:value,value}))]);
const conferences=computed(()=>sortConferences(store.conferences.filter(c=>(area.value==='all'||c.area===area.value)&&(!onlyPlanned.value||c.planned)),now.value));
const summaries=computed(()=>Object.fromEntries(store.conferences.map(c=>[c.key,conferenceSummary(c,now.value)])));
const isOpen=c=>!!c.pinned||!!expanded.value[c.key];
function toggle(c){if(!c.pinned)expanded.value[c.key]=!expanded.value[c.key];}
async function update(c,patch){if(busy.value[c.key])return;busy.value[c.key]=true;try{await updateConference(c,patch);if('pinned'in patch)delete expanded.value[c.key];return true;}catch(e){fail(e);if(e.status===409)await bootstrap()}finally{busy.value[c.key]=false}}
const target=computed(()=>store.conferences.find(c=>c.key===targetKey.value));
function openTarget(c){targetKey.value=c.key;targetProject.value=c.project_id;}
async function saveTarget(planned){if(!target.value)return;const saved=await update(target.value,planned?{planned:true,project_id:targetProject.value}:{planned:false});if(saved){targetKey.value=null;toast(planned?'已加入投稿计划，可在今日查看倒计时':'已取消投稿计划');}}
const local=m=>deadlineLocal(m.at,store.timezone);
const zoneLabel=computed(()=>store.timezone==='Asia/Singapore'?'新加坡':store.timezone);
async function locate(){if(!route.hash)return;const key=route.hash.slice(1);area.value='all';onlyPlanned.value=false;expanded.value[key]=true;await nextTick();document.getElementById(key)?.scrollIntoView({block:'start'});}
watch(()=>route.hash,locate,{immediate:true});
</script>
<template><div class="page submissions-page">
 <div class="page-head"><h1>投稿</h1><span class="muted">置顶常看，其余按最近节点排列</span></div>
 <div class="submission-toolbar"><NSelect v-model:value="area" :options="options" style="width:180px"/><NCheckbox v-model:checked="onlyPlanned">只看计划投稿</NCheckbox><span class="grow"/><span class="small muted">核对日期见各会议 · 时间显示为 {{ zoneLabel }}</span></div>
 <div class="conference-list"><article v-for="c in conferences" :key="c.key" :id="c.key" class="card conference-card" :class="{pinned:c.pinned,expanded:isOpen(c)}" :data-testid="`conference-${c.key}`">
  <header class="conference-row">
   <component :is="c.pinned?'div':'button'" :type="c.pinned?undefined:'button'" class="conference-summary" :aria-expanded="c.pinned?undefined:isOpen(c)" :aria-controls="c.pinned?undefined:`conference-details-${c.key}`" :aria-label="c.pinned?undefined:`${isOpen(c)?'收起':'展开'} ${c.name}`" :data-testid="`conference-summary-${c.key}`" @click="toggle(c)">
    <span class="conference-identity"><span class="conference-area">{{ c.area }}<span v-if="c.ccf"> · CCF {{ c.ccf }}</span><span v-if="c.pinned"> · 已置顶</span></span><span class="conference-name" role="heading" aria-level="2">{{ c.name }}</span></span>
    <span class="nearest-milestone" v-if="summaries[c.key].milestone"><span>{{ summaries[c.key].kind==='past'?'最近截止 · ':'' }}{{ summaries[c.key].milestone.cycle?summaries[c.key].milestone.cycle+' · ':'' }}{{ summaries[c.key].milestone.label }}</span><small>{{ local(summaries[c.key].milestone).date }} {{ local(summaries[c.key].milestone).time }}</small></span>
    <span class="nearest-milestone muted" v-else>{{ summaries[c.key].kind==='complete'?'暂无待办投稿节点':conferenceState(c,now) }}</span>
    <span v-if="summaries[c.key].kind==='upcoming'" class="nearest-count" :class="countdown(summaries[c.key].milestone.at,now).tone">{{ countdown(summaries[c.key].milestone.at,now).label }}</span>
    <span v-else-if="summaries[c.key].kind==='past'" class="nearest-count past">新投稿已截止</span>
    <span v-if="!c.pinned" class="row-chevron" :class="{open:isOpen(c)}" aria-hidden="true">⌄</span>
   </component>
   <div class="conference-actions"><NButton size="small" :secondary="c.planned" :type="c.planned?'primary':'default'" :disabled="busy[c.key]" :aria-label="`${c.planned?'管理投稿计划':'计划投稿'} ${c.name}`" @click="openTarget(c)">{{ c.planned?'已计划投稿':'计划投稿' }}</NButton><NButton size="small" quaternary :disabled="busy[c.key]" :aria-label="`${c.pinned?'取消置顶':'置顶'} ${c.name}`" @click="update(c,{pinned:!c.pinned})">{{ c.pinned?'取消置顶':'置顶' }}</NButton></div>
  </header>
  <div v-if="isOpen(c)" :id="`conference-details-${c.key}`" class="conference-details" :data-testid="`conference-details-${c.key}`">
   <p class="conference-note">{{ c.note }}</p>
   <div v-if="c.milestones.length" class="milestone-list"><div v-for="m in c.milestones" :key="m.id" class="milestone" :class="{done:c.completed[m.id],past:m.at&&Date.parse(m.at)<=now}" :data-testid="`milestone-${c.key}-${m.id}`">
    <NCheckbox v-if="m.action" :checked="!!c.completed[m.id]" :disabled="busy[c.key]" :aria-label="`${c.name} ${m.cycle||''} ${m.label} 已完成`" @update:checked="done=>update(c,{milestone_id:m.id,done})"/><span v-else class="milestone-dot"/>
    <div class="milestone-content"><div class="milestone-label">{{ m.cycle?m.cycle+' · ':'' }}{{ m.label }}</div><div class="milestone-date">{{ m.date }} {{ m.at?'23:59:59 ':'' }}{{ m.zone }}</div><RouterLink v-if="m.at" :to="{name:'calendar',query:{date:local(m).date}}" class="milestone-local">{{ local(m).date }} {{ local(m).time }} · {{ zoneLabel }} ›</RouterLink><span v-else class="small muted">公布日，具体时刻待官方通知</span><span v-if="m.requires&&!c.completed[m.requires]" class="small muted">适用于已投稿 / 已有评审的论文</span></div>
    <span class="milestone-count" :class="m.at?countdown(m.at,now).tone:''">{{ c.completed[m.id]?'已完成':m.at?countdown(m.at,now).label:'日期已公布' }}</span>
   </div></div>
   <div v-else class="pending-dates">{{ c.status==='pending'?'官方日期待公布':'暂未核实到官方截止日期' }}<small>确认后再加入倒计时与日历。</small></div>
   <div class="conference-project"><label :for="`project-${c.key}`">关联项目</label><NSelect :id="`project-${c.key}`" :value="c.project_id" :options="[...store.projects.map(p=>({value:p.id,label:p.name})),...(c.project_id&&!store.projects.some(p=>p.id===c.project_id)?[{value:c.project_id,label:c.project_name+'（归档）'}]:[])]" filterable clearable size="small" placeholder="可选，便于和研究任务一起查看" :disabled="busy[c.key]" @update:value="project_id=>update(c,{project_id})"/></div>
   <footer><a :href="c.source" target="_blank" rel="noopener noreferrer">官方来源 ↗</a><a v-if="c.ccf_source" :href="c.ccf_source" target="_blank" rel="noopener noreferrer">CCF {{ c.ccf_edition }} 目录（PDF）↗</a><span class="small muted">核对于 {{ c.checked_at }}</span></footer>
  </div>
 </article></div>
 <p v-if="!conferences.length" class="empty-conferences muted">没有符合筛选条件的会议。</p>
 <p class="small muted time-explainer">AOE 为 UTC−12，下面的时间已换算为{{ zoneLabel }}时间。倒计时每半分钟更新；未公布精确时刻的通知只显示日期。会议资料按官方公告核对更新，勾选用于记录你的提交进度。研究方向说明用于辅助选会；CCF 级别按所注版本，目录针对 Full / Regular papers，短文与 Workshop 不自动适用。</p>
 <NModal :show="!!target" preset="card" :title="target?.planned?'管理投稿计划':'确认投稿计划'" style="width:min(520px,94vw)" data-testid="submission-plan-dialog" @update:show="v=>{if(!v&&!busy[targetKey])targetKey=null}">
  <template v-if="target"><h3 class="target-name">{{ target.name }}</h3><p class="small target-explainer">确认后，这个会议会出现在今日、周计划和日程的投稿倒计时中。</p><p v-if="summaries[target.key].kind==='upcoming'" class="target-nearest">{{ summaries[target.key].milestone.label }} · {{ countdown(summaries[target.key].milestone.at,now).label }}<small>{{ local(summaries[target.key].milestone).date }} {{ local(summaries[target.key].milestone).time }} · {{ zoneLabel }}</small></p><p v-else class="small muted">{{ summaries[target.key].kind==='past'?'本届新投稿已截止，后续阶段适用于已提交的论文。':'日期确认后会显示对应倒计时。' }}</p><label class="target-project-label">关联项目（可选）</label><NSelect v-model:value="targetProject" :options="[...store.projects.map(p=>({value:p.id,label:p.name})),...(target.project_id&&!store.projects.some(p=>p.id===target.project_id)?[{value:target.project_id,label:target.project_name+'（归档）'}]:[])]" filterable clearable placeholder="选择研究项目" :disabled="busy[target.key]"/></template>
  <template #footer><div v-if="target" class="target-actions"><NButton v-if="target.planned" quaternary :disabled="busy[target.key]" @click="saveTarget(false)">取消投稿计划</NButton><span class="grow"/><NButton :disabled="busy[target.key]" @click="targetKey=null">返回</NButton><NButton type="primary" :loading="busy[target.key]" @click="saveTarget(true)">{{ target.planned?'保存':'确认投稿计划' }}</NButton></div></template>
 </NModal>
</div></template>
<style scoped>
.submission-toolbar{display:flex;flex-wrap:wrap;gap:16px;align-items:center;margin:0 0 22px}.time-explainer{line-height:1.8;margin-top:24px}.conference-list{display:flex;flex-direction:column;gap:12px}.conference-card{margin:0;min-width:0;padding:0;scroll-margin-top:20px;overflow:hidden}.conference-card.pinned{border-left:3px solid var(--accent)}.conference-row{display:flex;align-items:center;gap:18px;padding:19px 24px}.conference-summary{display:flex;align-items:center;gap:20px;flex:1;min-width:0;background:none;border:0;padding:0;text-align:left;font:inherit;color:var(--ink)}button.conference-summary{cursor:pointer}button.conference-summary:hover .conference-name{color:var(--accent-deep)}button.conference-summary:focus-visible{outline:2px solid var(--accent);outline-offset:6px;border-radius:3px}.conference-identity{display:grid;gap:5px;flex:0 0 200px;min-width:0}.conference-area{font-size:11px;color:var(--ink-2)}.conference-name{font-size:18px;font-weight:600;line-height:1.5;overflow-wrap:anywhere}.nearest-milestone{display:grid;gap:5px;flex:1;min-width:0;font-size:13px;line-height:1.6}.nearest-milestone small{font-size:12px;color:var(--ink-2);font-variant-numeric:tabular-nums}.nearest-count{font-size:14px;font-weight:600;color:var(--accent-deep);white-space:nowrap;font-variant-numeric:tabular-nums}.nearest-count.past{font-size:12px;font-weight:400;color:var(--ink-3)}.nearest-count.soon,.milestone-count.soon{color:var(--sand-deep)}.nearest-count.urgent,.milestone-count.urgent{color:var(--danger)}.row-chevron{font-size:20px;color:var(--ink-3);flex:none;transition:transform .15s}.row-chevron.open{transform:rotate(180deg)}.conference-details{padding:0 24px 22px}.conference-note{font-size:13px;color:var(--ink-2);line-height:1.8;padding-top:16px;margin:0 0 16px;border-top:1px solid var(--line-soft)}.milestone{display:grid;grid-template-columns:18px minmax(0,1fr) auto;gap:10px;padding:14px 0;border-top:1px solid var(--line-soft);align-items:start}.milestone-content{display:grid;grid-template-columns:minmax(200px,1fr) minmax(190px,1fr);gap:5px 20px;min-width:0}.milestone-label{font-size:13px;font-weight:500;grid-row:span 2}.milestone-date,.milestone-local{font-size:12px;color:var(--ink-2);text-decoration:none}.milestone-local{color:var(--accent-deep)}.milestone-content>.small{grid-column:2}.milestone-count{font-size:13px;font-weight:600;white-space:nowrap;color:var(--accent-deep)}.milestone-count.past,.milestone.past{color:var(--ink-3)}.milestone.done{background:var(--honey-mist);padding:14px 7px;border-radius:7px}.milestone-dot{width:6px;height:6px;background:var(--line);border-radius:50%;margin:6px}.conference-project{display:grid;grid-template-columns:72px minmax(0,480px);align-items:center;gap:12px;margin:20px 0}.conference-project label{font-size:12px;color:var(--ink-2)}.conference-details footer{display:flex;align-items:center;gap:16px;font-size:12px}.pending-dates{padding:20px;background:var(--surface-warm);color:var(--ink-2);display:grid;gap:8px;font-size:13px;border-radius:9px}.pending-dates small{font-size:12px}.empty-conferences{padding:30px 0;text-align:center}
.conference-actions{display:flex;align-items:center;gap:8px;flex:none}.target-name{margin-top:0;font-size:20px}.target-explainer{line-height:1.8}.target-nearest{background:var(--surface-warm);padding:14px;border-radius:8px;font-size:13px}.target-nearest small{display:block;margin-top:7px;color:var(--ink-2)}.target-project-label{display:block;margin:18px 0 8px;font-size:13px}.target-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
@media(max-width:1100px){.conference-identity{flex-basis:185px}.conference-summary{gap:16px}.milestone-content{display:grid;grid-template-columns:1fr}.milestone-label{grid-row:auto}.milestone-content>.small{grid-column:auto}}
@media(max-width:650px){.conference-actions{flex-direction:column;align-items:flex-end;gap:8px}.conference-row{align-items:flex-start;padding:16px;gap:8px}.conference-summary{display:grid;grid-template-columns:minmax(0,1fr) 18px;gap:8px 10px}.conference-identity{grid-column:1}.conference-name{font-size:17px}.nearest-milestone{grid-column:1;font-size:12px;gap:2px}.nearest-count{grid-column:1;font-size:13px}.row-chevron{grid-column:2;grid-row:1;align-self:center}.conference-details{padding:0 16px 18px}.milestone{grid-template-columns:18px minmax(0,1fr);gap:6px 9px}.milestone-count{grid-column:2}.conference-project{grid-template-columns:1fr;gap:7px}.conference-details footer{gap:10px;flex-wrap:wrap}.submission-toolbar{gap:12px}.submission-toolbar>.grow{display:none}}
</style>
